/**
 * NocoDB Node - Version 4
 * Discriminator: resource=row, operation=upload
 */


interface Credentials {
  nocoDb: CredentialReference;
  nocoDbApiToken: CredentialReference;
}

/** Upload attachment(s) to an existing cell in a row */
export type NocoDbV4RowUploadParams = {
  resource: 'row';
  operation: 'upload';
  authentication?: 'nocoDbApiToken' | 'nocoDb' | Expression<string>;
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @searchListMethod getWorkspaces
 * @default {"mode":"list","value":""}
 */
    workspaceId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @searchListMethod getBases
 * @default {"mode":"list","value":""}
 */
    projectId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The table to operate on. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @searchListMethod getTables
 * @default {"mode":"list","value":""}
 */
    table?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The value of the ID field
 */
    id: string | Expression<string>;
/**
 * Choose a way to perform the upload
 * @default base64
 */
    uploadMode?: 'base64' | 'url' | Expression<string>;
/**
 * Name of the fields of type 'attachment' that will be uploaded. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @searchListMethod getDownloadFieldsId
 * @displayOptions.show { uploadMode: ["base64"] }
 * @default {"mode":"list","value":""}
 */
    uploadFieldName?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Name of uploaded file
 * @displayOptions.show { uploadMode: ["base64"] }
 */
    filename: string | Expression<string>;
/**
 * Content type of file
 * @displayOptions.show { uploadMode: ["base64"] }
 */
    contentType: string | Expression<string>;
/**
 * Base64 value of file that will be upload
 * @displayOptions.show { uploadMode: ["base64"] }
 */
    base64value: string | Expression<string>;
/**
 * URL of file that will be uploaded
 * @displayOptions.show { uploadMode: ["url"] }
 */
    url: string | Expression<string>;
};

export type NocoDbV4RowUploadNode = {
  type: 'n8n-nodes-base.nocoDb';
  version: 4;
  config: NodeConfig<NocoDbV4RowUploadParams> & { credentials?: Credentials };
};